from pathlib import Path
import re, sys
root=Path(sys.argv[1])
api=root/'api'

api_php=r'''<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
require_once __DIR__.'/app_notifications_v140.php';
$caller=require_auth();$ctx=user_context();
if((string)($ctx['role']??'')!=='master')out(['data'=>null,'error'=>['message'=>'Somente o MASTER pode gerenciar vínculos de voluntários.']],403);
function mvl_t(string $t): bool {static $c=[];if(array_key_exists($t,$c))return$c[$t];try{$q=db()->prepare("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?");$q->execute([$t]);return$c[$t]=(int)$q->fetchColumn()>0;}catch(Throwable $e){return$c[$t]=false;}}
function mvl_c(string $t,string $c): bool {static $x=[];$k=$t.'.'.$c;if(array_key_exists($k,$x))return$x[$k];try{$q=db()->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?");$q->execute([$t,$c]);return$x[$k]=(int)$q->fetchColumn()>0;}catch(Throwable $e){return$x[$k]=false;}}
function mvl_roles(string $uid): array {try{$q=db()->prepare("SELECT role FROM user_roles WHERE BINARY user_id=BINARY ? ORDER BY role");$q->execute([$uid]);return array_values(array_unique(array_map('strval',$q->fetchAll(PDO::FETCH_COLUMN)?:[])));}catch(Throwable $e){return[];}}
function mvl_church(?string $id): ?array {if(!$id)return null;$q=db()->prepare("SELECT id,nome FROM igrejas WHERE BINARY id=BINARY ? LIMIT 1");$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);return$r?:null;}
function mvl_member(string $uid): ?array {$emailSql=mvl_t('users')?"(SELECT u.email FROM users u WHERE BINARY u.id=BINARY p.id LIMIT 1) email":"NULL email";$q=db()->prepare("SELECT p.id,p.nome,p.whatsapp,p.igreja_id,$emailSql,(SELECT i.nome FROM igrejas i WHERE BINARY i.id=BINARY p.igreja_id LIMIT 1) igreja_nome FROM profiles p WHERE BINARY p.id=BINARY ? LIMIT 1");$q->execute([$uid]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)return null;$r['roles']=mvl_roles($uid);return$r;}
function mvl_list(): array {$emailSql=mvl_t('users')?"(SELECT u.email FROM users u WHERE BINARY u.id=BINARY p.id LIMIT 1) email":"NULL email";$sql="SELECT p.id,p.nome,p.whatsapp,p.igreja_id,$emailSql,(SELECT i.nome FROM igrejas i WHERE BINARY i.id=BINARY p.igreja_id LIMIT 1) igreja_nome,(SELECT GROUP_CONCAT(DISTINCT r.role ORDER BY r.role SEPARATOR ',') FROM user_roles r WHERE BINARY r.user_id=BINARY p.id) roles FROM profiles p WHERE EXISTS(SELECT 1 FROM user_roles rv WHERE BINARY rv.user_id=BINARY p.id AND rv.role IN ('voluntario','lider')) AND NOT EXISTS(SELECT 1 FROM user_roles ra WHERE BINARY ra.user_id=BINARY p.id AND ra.role IN ('master','admin')) ORDER BY COALESCE(p.nome,''),p.id";return db()->query($sql)->fetchAll(PDO::FETCH_ASSOC)?:[];}
function mvl_delete_user_rows(string $table,string $column,string $uid): int {if(!mvl_t($table)||!mvl_c($table,$column))return 0;$q=db()->prepare("DELETE FROM `$table` WHERE BINARY `$column`=BINARY ?");$q->execute([$uid]);return$q->rowCount();}
function mvl_reset_org_links(string $uid): array {$o=[];$o['departamentos_voluntario']=mvl_delete_user_rows('departamento_voluntarios','voluntario_id',$uid);$o['tags']=mvl_delete_user_rows('voluntario_tags','voluntario_id',$uid);$o['localizacoes']=mvl_delete_user_rows('volunteer_locations','user_id',$uid);$o['sessoes_whatsapp']=mvl_delete_user_rows('whatsapp_pending_sessions','voluntario_id',$uid);if(mvl_t('departamentos')&&mvl_c('departamentos','lider_id')){$q=db()->prepare("UPDATE departamentos SET lider_id=NULL WHERE BINARY lider_id=BINARY ?");$q->execute([$uid]);$o['liderancas_departamento']=$q->rowCount();}else$o['liderancas_departamento']=0;return$o;}
function mvl_normalize_volunteer_role(string $uid): void {db()->prepare("DELETE FROM user_roles WHERE BINARY user_id=BINARY ? AND role='lider'")->execute([$uid]);$q=db()->prepare("SELECT COUNT(*) FROM user_roles WHERE BINARY user_id=BINARY ? AND role='voluntario'");$q->execute([$uid]);if((int)$q->fetchColumn()===0)db()->prepare("INSERT INTO user_roles(id,user_id,role) VALUES(?,?,'voluntario')")->execute([uuid4(),$uid]);}
function mvl_is_principal_admin(string $uid): bool {if(!mvl_t('saas_church_access')||!mvl_c('saas_church_access','admin_user_id'))return false;try{$q=db()->prepare("SELECT COUNT(*) FROM saas_church_access WHERE BINARY admin_user_id=BINARY ?");$q->execute([$uid]);return(int)$q->fetchColumn()>0;}catch(Throwable $e){return false;}}
$req=$_SERVER['REQUEST_METHOD']==='POST'?input_json():$_GET;$action=(string)($req['action']??'list');
try{
 if($action==='list'){$churches=db()->query('SELECT id,nome FROM igrejas ORDER BY nome')->fetchAll(PDO::FETCH_ASSOC)?:[];$people=mvl_list();$linked=0;foreach($people as$r)if(!empty($r['igreja_id']))$linked++;out(['data'=>['churches'=>$churches,'people'=>$people,'summary'=>['total'=>count($people),'linked'=>$linked,'unlinked'=>count($people)-$linked]],'error'=>null]);}
 if(!in_array($action,['link','unlink'],true))throw new RuntimeException('Ação inválida.');
 $uid=trim((string)($req['user_id']??''));if($uid==='')throw new RuntimeException('Selecione um voluntário.');$member=mvl_member($uid);if(!$member)throw new RuntimeException('Voluntário não encontrado.');$roles=$member['roles']??[];
 if(in_array('master',$roles,true)||in_array('admin',$roles,true))throw new RuntimeException('Contas MASTER ou administradores de igreja não podem ser movidas por esta tela.');
 if(!in_array('voluntario',$roles,true)&&!in_array('lider',$roles,true))throw new RuntimeException('Este usuário não está cadastrado como voluntário/líder.');if(mvl_is_principal_admin($uid))throw new RuntimeException('Este usuário é administrador principal de uma igreja. Transfira a administração antes de alterar o vínculo.');
 $oldId=trim((string)($member['igreja_id']??''));$newId=null;$newChurch=null;
 if($action==='link'){$newId=trim((string)($req['igreja_id']??''));if($newId==='')throw new RuntimeException('Escolha a igreja de destino.');$newChurch=mvl_church($newId);if(!$newChurch)throw new RuntimeException('Igreja de destino não encontrada.');if($oldId!==''&&hash_equals($oldId,$newId))out(['data'=>['ok'=>true,'unchanged'=>true,'member'=>mvl_member($uid)],'error'=>null]);}else if($oldId==='')out(['data'=>['ok'=>true,'unchanged'=>true,'member'=>mvl_member($uid)],'error'=>null]);
 $oldChurch=mvl_church($oldId?:null);$pdo=db();$pdo->beginTransaction();try{$clean=mvl_reset_org_links($uid);mvl_normalize_volunteer_role($uid);$sql=mvl_c('profiles','updated_at')?'UPDATE profiles SET igreja_id=?,updated_at=NOW() WHERE BINARY id=BINARY ?':'UPDATE profiles SET igreja_id=? WHERE BINARY id=BINARY ?';$pdo->prepare($sql)->execute([$newId,$uid]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
 $name=trim((string)($member['nome']??''))?:'Voluntário';if($newChurch){appn_v140_create($uid,$newId,'church_link','Vínculo com igreja atualizado','Sua conta foi vinculada à igreja '.$newChurch['nome'].'.','/perfil','normal','master-church-link:'.$uid.':'.$newId.':'.date('YmdHis'));}else{appn_v140_create($uid,null,'church_unlink','Vínculo com igreja removido','Sua conta foi desvinculada da igreja pelo administrador do sistema.','/perfil','normal','master-church-unlink:'.$uid.':'.date('YmdHis'));}
 try{audit((string)($caller['id']??''),$action==='link'?'master_volunteer_link':'master_volunteer_unlink','profiles',['user_id'=>$uid,'nome'=>$name,'old_igreja_id'=>$oldId?:null,'old_igreja_nome'=>$oldChurch['nome']??null,'new_igreja_id'=>$newId,'new_igreja_nome'=>$newChurch['nome']??null,'organizational_links_reset'=>$clean],'warning');}catch(Throwable $e){}out(['data'=>['ok'=>true,'action'=>$action,'member'=>mvl_member($uid),'old_church'=>$oldChurch,'new_church'=>$newChurch,'reset'=>$clean,'history_preserved'=>true],'error'=>null]);
}catch(Throwable $e){out(['data'=>null,'error'=>['message'=>$e->getMessage()]],400);}'''
(api/'master-volunteer-links.php').write_text(api_php,encoding='utf-8')

html=r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vínculos de voluntários — MASTER</title><style>*{box-sizing:border-box}body{margin:0;font:14px Arial,sans-serif;background:#f4f7fb;color:#172033}.w{max-width:1120px;margin:auto;padding:20px}.hero,.panel{background:#fff;border:1px solid #dfe6ef;border-radius:18px;padding:18px}.hero{margin-bottom:14px}.hero h1{margin:0 0 6px;font-size:24px}.muted{color:#69788d}.note{margin-top:12px;padding:11px 12px;border-radius:12px;background:#eef5ff;border:1px solid #cfdef8;color:#274d83}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.stat{background:#fff;border:1px solid #e0e7f0;border-radius:14px;padding:14px}.stat b{display:block;font-size:24px}.filters{display:grid;grid-template-columns:1.4fr 1fr;gap:10px;margin-bottom:14px}input,select{width:100%;min-height:44px;border:1px solid #ccd7e5;border-radius:10px;padding:0 11px;background:#fff;font-size:14px}.list{display:grid;gap:10px}.row{display:grid;grid-template-columns:minmax(210px,1.35fr) minmax(170px,.9fr) minmax(190px,1fr) auto;gap:12px;align-items:center;border:1px solid #e1e8f0;border-radius:14px;padding:13px;background:#fff}.name{font-weight:800;font-size:15px}.contact{font-size:12px;color:#718095;margin-top:4px;overflow-wrap:anywhere}.church{font-weight:700}.none{color:#a15323}.badges{display:flex;gap:5px;flex-wrap:wrap;margin-top:5px}.badge{font-size:10px;padding:3px 7px;border-radius:999px;background:#eef2f7;color:#526176}.actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.actions select{min-width:180px;max-width:220px}.btn{min-height:42px;border:0;border-radius:10px;padding:0 12px;font-weight:800;cursor:pointer}.primary{background:#1764e8;color:#fff}.danger{background:#fff0f0;color:#a82626;border:1px solid #efc1c1}.btn:disabled{opacity:.5;cursor:not-allowed}.msg{display:none;margin-bottom:12px;padding:11px;border-radius:10px}.ok{display:block;background:#eaf8ef;color:#17643a}.err{display:block;background:#fff0f0;color:#9a2525}.info{display:block;background:#edf4ff;color:#234d89}.empty{padding:24px;text-align:center;color:#748298}@media(max-width:860px){.row{grid-template-columns:1fr}.actions select{max-width:none;flex:1}.filters{grid-template-columns:1fr}}@media(max-width:560px){.w{padding:12px}.stats{grid-template-columns:1fr}.actions{display:grid;grid-template-columns:1fr}.actions select{min-width:0}.btn{width:100%}}</style></head><body><main class="w"><section class="hero"><h1>👥 Vínculos de voluntários</h1><div class="muted">Exclusivo do MASTER para vincular, mover ou desvincular voluntários das igrejas.</div><div class="note"><b>O histórico não é apagado.</b> Escalas, presenças e respostas antigas permanecem registradas na igreja original. Ao mudar ou remover o vínculo, departamentos, tags, localização atual e função de líder são retirados para não carregar permissões de uma igreja para outra.</div></section><section class="stats"><div class="stat"><b id="stTotal">—</b><span class="muted">Voluntários/líderes</span></div><div class="stat"><b id="stLinked">—</b><span class="muted">Vinculados</span></div><div class="stat"><b id="stUnlinked">—</b><span class="muted">Sem igreja</span></div></section><section class="panel"><div id="msg" class="msg"></div><div class="filters"><input id="search" placeholder="Buscar por nome, WhatsApp ou e-mail"><select id="filter"><option value="all">Todas as igrejas</option><option value="unlinked">Somente sem igreja</option></select></div><div id="list" class="list"><div class="empty">Carregando voluntários...</div></div></section></main><script>const token=localStorage.getItem('escala-facil.auth-token')||'',H={'Content-Type':'application/json',Accept:'application/json',...(token?{Authorization:'Bearer '+token}:{})},$=x=>document.getElementById(x);let data={churches:[],people:[],summary:{}},busy=false;function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function msg(t,c='info'){$('msg').className='msg '+c;$('msg').textContent=t;window.scrollTo({top:0,behavior:'smooth'})}async function api(b){const r=await fetch('/api/master-volunteer-links.php',{method:'POST',credentials:'include',headers:H,body:JSON.stringify(b)});let j={};try{j=await r.json()}catch{}if(!r.ok||j.error)throw new Error(j?.error?.message||'Falha na operação');return j.data}function churchName(id){const c=data.churches.find(x=>x.id===id);return c?.nome||'Igreja'}function roleBadges(roles){return String(roles||'').split(',').filter(Boolean).map(x=>`<span class="badge">${esc(x==='lider'?'Líder':'Voluntário')}</span>`).join('')}function churchOpts(current){return '<option value="">Escolher igreja de destino...</option>'+data.churches.map(c=>`<option value="${esc(c.id)}" ${c.id===current?'disabled':''}>${esc(c.nome)}${c.id===current?' (atual)':''}</option>`).join('')}function render(){const q=$('search').value.trim().toLowerCase(),f=$('filter').value;let rows=data.people.filter(p=>{const hay=[p.nome,p.whatsapp,p.email,p.igreja_nome].join(' ').toLowerCase();if(q&&!hay.includes(q))return false;if(f==='unlinked')return!p.igreja_id;if(f!=='all')return p.igreja_id===f;return true});$('list').innerHTML=rows.length?rows.map(p=>`<article class="row" data-id="${esc(p.id)}"><div><div class="name">${esc(p.nome||'Sem nome')}</div><div class="contact">${esc(p.whatsapp||'Sem WhatsApp')}${p.email?' · '+esc(p.email):''}</div><div class="badges">${roleBadges(p.roles)}</div></div><div><div class="muted">Igreja atual</div><div class="church ${p.igreja_id?'':'none'}">${esc(p.igreja_nome||'Sem igreja')}</div></div><div><select class="dest">${churchOpts(p.igreja_id||'')}</select></div><div class="actions"><button class="btn primary link" ${busy?'disabled':''}>${p.igreja_id?'Mover':'Vincular'}</button><button class="btn danger unlink" ${!p.igreja_id||busy?'disabled':''}>Desvincular</button></div></article>`).join(''):'<div class="empty">Nenhum voluntário encontrado com esses filtros.</div>';document.querySelectorAll('.link').forEach(b=>b.addEventListener('click',onLink));document.querySelectorAll('.unlink').forEach(b=>b.addEventListener('click',onUnlink))}function fill(){const s=data.summary||{};$('stTotal').textContent=s.total??data.people.length;$('stLinked').textContent=s.linked??data.people.filter(x=>x.igreja_id).length;$('stUnlinked').textContent=s.unlinked??data.people.filter(x=>!x.igreja_id).length;$('filter').innerHTML='<option value="all">Todas as igrejas</option><option value="unlinked">Somente sem igreja</option>'+data.churches.map(c=>`<option value="${esc(c.id)}">${esc(c.nome)}</option>`).join('');render()}async function load(){try{data=await api({action:'list'});fill()}catch(e){msg(e.message,'err');$('list').innerHTML='<div class="empty">Não foi possível carregar os voluntários.</div>'}}function person(id){return data.people.find(x=>x.id===id)}async function onLink(e){const row=e.currentTarget.closest('.row'),id=row.dataset.id,dest=row.querySelector('.dest').value,p=person(id);if(!dest){msg('Escolha a igreja de destino para '+(p?.nome||'o voluntário')+'.','err');return}const name=churchName(dest);if(!confirm(`Confirma ${p?.igreja_id?'mover':'vincular'} ${p?.nome||'este voluntário'} para ${name}?\n\nO histórico antigo será preservado. Vínculos de departamento e função de líder serão removidos.`))return;await mutate({action:'link',user_id:id,igreja_id:dest},`${p?.nome||'Voluntário'} foi vinculado a ${name}.`)}async function onUnlink(e){const row=e.currentTarget.closest('.row'),id=row.dataset.id,p=person(id);if(!confirm(`Desvincular ${p?.nome||'este voluntário'} de ${p?.igreja_nome||'sua igreja'}?\n\nA conta continuará existindo e o histórico antigo não será apagado.`))return;await mutate({action:'unlink',user_id:id},`${p?.nome||'Voluntário'} ficou sem vínculo com igreja.`)}async function mutate(body,ok){if(busy)return;busy=true;render();msg('Atualizando vínculo...','info');try{await api(body);msg(ok,'ok');data=await api({action:'list'});fill()}catch(e){msg(e.message,'err')}finally{busy=false;render()}}$('search').addEventListener('input',render);$('filter').addEventListener('change',render);load();</script></body></html>'''
(root/'master-voluntarios.html').write_text(html,encoding='utf-8')

